 */
export async function runDbMigrations() {
  try {
    const db = getDb();
    await migrate(db, { migrationsFolder: path.join(__dirname, '..', 'drizzle') });
  } catch (error) {
    logger.error('Error running database migrations:', error);
  }
}

if (require.main === module) {
  runDbMigrations();
